ORIGINAL_SOURCE_ITEM = shared.source_item


def scoped_source_item(source_id: str, verse: int, text: str) -> dict:
    result = ORIGINAL_SOURCE_ITEM(source_id, verse, text)
    if source_id == "en_tafheem_ul_quran":
        if verse <= 14:
            group_key, group_label = "11–14", "۴:۱۱–۱۴"
        elif verse <= 22:
            group_key, group_label = "15–22", "۴:۱۵–۲۲"
        else:
            group_key, group_label = "23–25", "۴:۲۳–۲۵"
        result["sourceUrl"] = TAFHEEM_GROUPS[group_key]
        result["cite"] = (
            f"مودودی، *تفہیم القرآن*، ذیلِ نساء ۴:{verse}؛ "
            f"شرحِ گروهیِ واقعیِ {group_label}."
        )
        result["evidence"] = f"موضعِ بررسی: شرحِ گروهیِ واقعیِ {group_label}؛ خلاصه به همان دامنه متصل است."
    return result


# build_entry resolves source_item through this module global.
shared.source_item = scoped_source_item


def build_catalog(registry: dict) -> dict:
    collection = shared.build_catalog(registry)
    collection["id"] = COLLECTION_ID
    collection["title"] = "منابعِ تفسیریِ مورد استناد در بستهٔ نساء ۴:۱۳–۲۴"
    for source in collection["items"]:
        source_id = source["id"]
        source["scope"] = "نساء ۴:۱۳–۲۴"
        if source_id in CLASSICAL_IDS:
            source["sourceUrl"] = shared.SOURCE_META[source_id]["url"].format(verse=13)
        elif source_id == "en_tafheem_ul_quran":
            source["sourceUrl"] = TAFHEEM_GROUPS["11–14"]
            source["sourceUrls"] = list(TAFHEEM_GROUPS.values())
        source["basis"] = {
            "ar_tabari_qurancom": "صفحه‌های آیه‌محورِ طبری برای آیاتِ ۴:۱۳–۲۴ به صورتِ مستقیم بررسی شدند؛ هر خلاصه به شمارهٔ آیهٔ خود متصل است.",
            "ar_ibn_kathir_qurancom": "صفحه‌های آیه‌محورِ ابن‌کثیر برای آیاتِ ۴:۱۳–۲۴ به صورتِ مستقیم بررسی شدند؛ اختلافِ اقوال به نامِ منبع ثبت شده است.",
            "ar_jalalayn_qurancom": "صفحه‌های آیه‌محورِ جلالین برای آیاتِ ۴:۱۳–۲۴ به صورتِ مستقیم بررسی شدند؛ شرح‌های نحوی و فقهی به مفسر نسبت داده شده‌اند.",
            "ar_tusi_tibyan": "صفحه‌های مستقیمِ GreatTafsirs برای آیاتِ ۴:۱۳–۲۴ بررسی شدند؛ چاپ و شمارهٔ صفحهٔ کتاب احراز یا حدس زده نشده است.",
            "ar_fayd_safi": "صفحه‌های مستقیمِ GreatTafsirs برای آیاتِ ۴:۱۳–۲۴ بررسی شدند؛ روایت‌های امامی به مؤلف و ناقلان منسوب‌اند.",
            "ar_qe_arabic_moyassar": "متنِ محلیِ آیه‌به‌آیهٔ QuranEnc برای نساء ۴:۱۳–۲۴ بررسی شد؛ منبعِ ترجمه و نسخه در رجیستری آمده است.",
            "en_tafheem_ul_quran": "سه دامنهٔ واقعیِ ۴:۱۱–۱۴، ۴:۱۵–۲۲ و ۴:۲۳–۲۵ مقابله شدند؛ ترجمه، یادداشتِ مستقل و شرحِ گروهی از هم تفکیک شده‌اند.",
        }[source_id]
    collection["comparativeCore"] = {
        "scope": "هر آیهٔ نساء ۴:۱۳–۲۴",
        "sunniSourceIds": sorted(SUNNI_IDS),
        "shiaSourceIds": sorted(SHIA_IDS),
        "note": "در هر یک از دوازده پرونده، سه تفسیرِ اهل‌سنت و دو تفسیرِ امامیه با پیوندِ مستقیمِ آیه‌محور و خلاصهٔ منسوب به‌کار رفته‌اند؛ قرآن‌انک و تفهیم القرآن شرح‌های افزوده‌اند و سه مدلِ معناشناختی کاربستِ تحریری دارند.",
    }
    collection["notice"] = "خلاصه‌ها نقلِ لفظی نیستند؛ پیوند یا خلاصه به‌معنای بازنشرِ متنِ کامل یا احرازِ مجوز نیست. دامنهٔ واقعیِ هر صفحه در پروندهٔ آیه‌ای مشخص شده است."
    return collection


def main() -> None:
    dossier = json.loads(DOSSIER_PATH.read_text(encoding="utf-8"))
    for verse, record in DATA.items():
        dossier["verses"][f"4:{verse}"] = shared.build_entry(verse, record)

    dossier["batches"] = [batch for batch in dossier["batches"] if batch["id"] != BATCH_ID]
    nisa_end, nisa_gap = nisa_coverage(dossier["verses"])
    dossier["batches"].append({
        "id": BATCH_ID,
        "title": "بستهٔ سی‌وسوم: نساء ۴:۱۳–۲۴؛ حدود، توبه و حقوقِ خانواده",
        "range": "4:13–24",
        "count": 12,
        "status": f"۱۲ پروندهٔ آیه‌محور با دست‌کم پنج بندِ مستند در هر یک از شش فیلد؛ در هر آیه پنج تفسیرِ کهن (سه اهل‌سنت و دو امامیه)، دو شرحِ معاصر و سه کاربردِ معناشناختی آمده است؛ پیش‌نویسِ نیازمندِ بازبینیِ تخصصی؛ {nisa_gap}.",
    })
    dossier["batches"].sort(key=lambda batch: int(batch["id"].split("-")[1]))
    for batch in dossier["batches"]:
        if batch.get("range", "").startswith("4:") and "؛ نساء ۴:" in batch.get("status", ""):
            prefix = batch["status"].split("؛ نساء ۴:", 1)[0]
            batch["status"] = f"{prefix}؛ {nisa_gap}."
    end_fa = str(nisa_end).translate(str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹"))
    dossier["notice"] = (
        "این پرونده‌ها پیش‌نویس‌های تحریریِ منبع‌محورند و بازبینیِ تخصصی را پشت سر نگذاشته‌اند. "
        f"نساء در این checkout بازهٔ ۴:۱–{end_fa} را پوشش می‌دهد؛ {nisa_gap}. "
        "بسته‌های یونس بازه‌های ۱۰:۴۹–۶۰، ۱۰:۶۱–۷۲ و ۱۰:۷۳–۸۴ را پوشش می‌دهند؛ برای ۱۰:۱–۴۸ پرونده‌ای ساخته نشده است. "
        "این داده‌ها ادعای تکمیلِ هیچ‌یک از دو سوره یا کل قرآن را نمی‌کنند. خلاصه‌ها نقلِ لفظی نیستند؛ اختلافِ اقوال و دامنهٔ واقعیِ صفحاتِ گروهی جدا ثبت شده و هیچ بند بازبینیِ تخصصی‌شده معرفی نمی‌شود."
    )
    method = dossier["editorialMethod"]
    method = method.replace("نساء ۴:۱۳–۱۷۶ هنوز در این checkout پوشش ندارد", f"{nisa_gap} در این checkout")
    method = method.replace("نساء ۴:۱۳–۱۷۶ هنوز پوشش ندارد", nisa_gap)
    method = method.replace("نساء ۴:۲۵–۱۷۶ هنوز پوشش ندارد", nisa_gap)
    addition = (
        " در بستهٔ نساء ۴:۱۳–۲۴، سه تفسیرِ اهل‌سنت و دو تفسیرِ امامیه با پیوندهای مستقیم ثبت شده‌اند؛ "
        "تفسیرهای «جهالة» و «قريب» در ۴:۱۷–۱۸، دیدگاه‌های گوناگون دربارهٔ «لا تعضلوهن» در ۴:۱۹، "
        "اختلافِ رضاع و مصاهره در ۴:۲۳، و نزاعِ خوانشِ متعه/نکاح در ۴:۲۴ یکسان‌سازی نشده‌اند. "
        "تفهیم القرآن به دامنه‌های واقعیِ ۴:۱۱–۱۴، ۴:۱۵–۲۲ و ۴:۲۳–۲۵ ارجاع می‌دهد؛ "
        "خوانشِ تاریخیِ برده‌داری در ۴:۲۴ تأییدِ اخلاقی یا کاربردِ معاصر معرفی نمی‌شود. "
        f"این دوازده پرونده پیش‌نویس‌اند و نیازمندِ بازبینیِ تخصصی هستند؛ {nisa_gap}."
    )
    if "در بستهٔ نساء ۴:۱۳–۲۴" not in method:
        method += addition
    dossier["editorialMethod"] = method
    DOSSIER_PATH.write_text(json.dumps(dossier, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    registry = json.loads((STATIC / "tafsir-sources.json").read_text(encoding="utf-8"))
    catalog = json.loads(CATALOG_PATH.read_text(encoding="utf-8"))
    catalog["collections"] = [
        item for item in catalog["collections"] if item["id"] != COLLECTION_ID
    ]
    catalog["collections"].append(build_catalog(registry))
    catalog["version"] = max(int(catalog.get("version", 0)), 9)
    CATALOG_PATH.write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Added {len(DATA)} dossiers; total={len(dossier['verses'])}; batch=4:13–24")


if __name__ == "__main__":
    main()
